# [maint-note:6f6a0ccf25e8]
# 维护导航：_format_memory_items；下列为本函数源码中的接口与路径索引。
# 输入 memories：list[dict[str, Any]]。
# 返回契约：str。
# 遍历边界：memory ← memories。
# 返回路径：'\n'.join(rows)。
# 直接调用：memory.get。
# 直接调用：' '.join。
# 直接调用：escape。
# 直接调用：str。
# 直接调用：attributes.items。
# 直接调用：rows.append。
# 直接调用：'\n'.join。
# 集合派生：(name, value) 来自 attributes.items()。
# [/maint-note:6f6a0ccf25e8]
def _format_memory_items(memories: list[dict[str, Any]]) -> str:
    rows: list[str] = []
    for memory in memories:
        attributes = {
            "id": memory.get("id", ""),
            "scope": memory.get("scope", ""),
            "kind": memory.get("kind", ""),
            "verification": memory.get("verification", ""),
        }
        rendered_attributes = " ".join(
            f'{name}="{escape(str(value), quote=True)}"'
            for name, value in attributes.items()
        )
        subject = escape(str(memory.get("subject", "")))
        content = escape(str(memory.get("content", "")))
        rows.append(
            f'<memory {rendered_attributes} untrusted="true">'
            f"<subject>{subject}</subject><content>{content}</content></memory>"
        )
    return "\n".join(rows)


# [maint-note:5e23393c3a5e]
# 维护导航：_format_runtime_authorization；下列为本函数源码中的接口与路径索引。
# 输入 value：dict[str, Any]。
# 返回契约：str。
# 返回路径：f'<workspace>{workspace}</workspace><target_files>{target_files}</target_files><authorized_paths description="user-authorized external paths">{authorized_paths}</authorized_paths>'。
# 直接调用：escape。
# 直接调用：str。
# 直接调用：value.get。
# 直接调用：''.join。
# 集合派生：path 来自 value.get('target_files', [])。
# 集合派生：path 来自 value.get('authorized_paths', [])。
# [/maint-note:5e23393c3a5e]
def _format_runtime_authorization(value: dict[str, Any]) -> str:
    workspace = escape(str(value.get("workspace", "")))
    target_files = "".join(
        f"<path>{escape(str(path))}</path>"
        for path in value.get("target_files", [])
    )
    authorized_paths = "".join(
        f"<path>{escape(str(path))}</path>"
        for path in value.get("authorized_paths", [])
    )
    return (
        f"<workspace>{workspace}</workspace>"
        f"<target_files>{target_files}</target_files>"
        '<authorized_paths description="user-authorized external paths">'
        f"{authorized_paths}</authorized_paths>"
    )


class ContextPlanner:
    # [maint-note:44e651e0aa26]
    # 维护导航：__init__；下列为本函数源码中的接口与路径索引。
    # 输入 counter：DeepSeekTokenCounter。
    # 输入 serializer：DeepSeekRequestSerializer。
    # 输入 profile：DeepSeekModelProfile。
    # 返回契约：None。
    # 写入目标：self.counter。
    # 写入目标：self.serializer。
    # 写入目标：self.profile。
    # [/maint-note:44e651e0aa26]
    def __init__(
        self,
        counter: DeepSeekTokenCounter,
        serializer: DeepSeekRequestSerializer,
        profile: DeepSeekModelProfile,
    ) -> None:
        self.counter = counter
        self.serializer = serializer
        self.profile = profile

    # [maint-note:725db6776be8]
    # 维护导航：plan；下列为本函数源码中的接口与路径索引。
    # 输入 system_rules：str。
    # 输入 goal：str。
    # 输入 messages：list[dict[str, Any]]。
    # 输入 active_state：dict[str, Any]。
    # 输入 memories：list[dict[str, Any]]。
    # 输入 tools：list[dict[str, Any]]。
    # 输入 checkpoint：dict[str, Any] | None；缺省表达式 None。
    # 输入 reserved_output_tokens：int | None；缺省表达式 None。
    # 输入 pinned_memories：list[dict[str, Any]] | None；缺省表达式 None。
    # 输入 runtime_authorization：dict[str, Any] | None；缺省表达式 None。
    # 输入 profile：DeepSeekModelProfile | None；缺省表达式 None。
    # 返回契约：ContextPlan。
    # 返回路径：self._build_plan(system_rules=system_rules, goal=goal, messages=messages, active_state=active_state, memories=memories, pinned_memories=list(pinned_memories or []), tools=tools, checkpoint=checkpoint, reserved_output_tokens=reserved_output_。
    # 直接调用：self._build_plan。
    # 直接调用：list。
    # [/maint-note:725db6776be8]
    def plan(
        self,
        *,
        system_rules: str,
        goal: str,
        messages: list[dict[str, Any]],
        active_state: dict[str, Any],
        memories: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        checkpoint: dict[str, Any] | None = None,
        reserved_output_tokens: int | None = None,
        pinned_memories: list[dict[str, Any]] | None = None,
        runtime_authorization: dict[str, Any] | None = None,
        profile: DeepSeekModelProfile | None = None,
    ) -> ContextPlan:
        return self._build_plan(
            system_rules=system_rules,
            goal=goal,
            messages=messages,
            active_state=active_state,
            memories=memories,
            pinned_memories=list(pinned_memories or []),
            tools=tools,
            checkpoint=checkpoint,
            reserved_output_tokens=reserved_output_tokens,
            runtime_authorization=runtime_authorization or {},
            profile=profile or self.profile,
        )

    # [maint-note:f38cfca970b0]
    # 维护导航：_build_plan；下列为本函数源码中的接口与路径索引。
    # 输入 system_rules：str。
    # 输入 goal：str。
    # 输入 messages：list[dict[str, Any]]。
    # 输入 active_state：dict[str, Any]。
    # 输入 memories：list[dict[str, Any]]。
    # 输入 pinned_memories：list[dict[str, Any]]。
    # 输入 tools：list[dict[str, Any]]。
    # 输入 checkpoint：dict[str, Any] | None。
    # 输入 reserved_output_tokens：int | None。
    # 输入 runtime_authorization：dict[str, Any]。
    # 输入 profile：DeepSeekModelProfile。
    # 返回契约：ContextPlan。
    # 分支条件：protected.total_with_reserve <= protected.context_window_tokens。
    # 分支条件：retained_memories。
    # 分支条件：requires_compaction。
    # 分支条件：full_breakdown.total_with_reserve <= selection_limit。
    # 分支条件：candidate_breakdown.total_with_reserve > selection_limit。
    # 分支条件：open_groups。
    # 分支条件：selected_start > earliest_open。
    # 分支条件：retained_start > 0。
    # 分支条件：any((not group.closed for group in omitted_groups))。
    # 遍历边界：retained_pinned_memories or retained_memories。
    # 遍历边界：group ← reversed(groups)。
    # 返回路径：ContextPlan(messages=planned_messages, tools=self.serializer.serialize_tools(tools), breakdown=breakdown, system_tokens=self.counter.count_text(category_text['system']), working_state_tokens=self.counter.count_text(category_text['working_st。
    # 显式抛出：ContextHardLimitExceeded(breakdown)。
    # 直接调用：list。
    # 直接调用：self._system_message。
    # 直接调用：self.counter.count_request。
    # 直接调用：retained_memories.pop。
    # 直接调用：retained_pinned_memories.pop。
    # 直接调用：self.counter.assert_fits。
    # 直接调用：int。
    # 直接调用：self._exchange_groups。
    # 直接调用：reversed。
    # 直接调用：min。
    # 直接调用：len。
    # 直接调用：range。
    # 直接调用：any。
    # 直接调用：ContextHardLimitExceeded。
    # 直接调用：json.dumps。
    # 直接调用：ContextPlan。
    # 直接调用：self.serializer.serialize_tools。
    # 直接调用：self.counter.count_text。
    # 集合派生：candidate_group 来自 candidate_groups。
    # 集合派生：message 来自 candidate_group.messages。
    # 集合派生：group 来自 groups；过滤 not group.closed。
    # 集合派生：group 来自 open_groups。
    # 表达式分流：selected_groups；真值与假值分支分别计算，不同时执行。
    # 集合派生：group 来自 groups；过滤 group.start >= earliest_open。
    # 集合派生：group 来自 selected_groups。
    # 集合派生：message 来自 group.messages。
    # 集合派生：group 来自 groups；过滤 group.end < retained_start。
    # 集合派生：group 来自 omitted_groups。
    # [/maint-note:f38cfca970b0]
    def _build_plan(
        self,
        *,
        system_rules: str,
        goal: str,
        messages: list[dict[str, Any]],
        active_state: dict[str, Any],
        memories: list[dict[str, Any]],
        pinned_memories: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        checkpoint: dict[str, Any] | None,
        reserved_output_tokens: int | None,
        runtime_authorization: dict[str, Any],
        profile: DeepSeekModelProfile,
    ) -> ContextPlan:
        retained_pinned_memories = list(pinned_memories)
        retained_memories = list(memories)
        system_message, runtime_context, category_text = self._system_message(
            system_rules,
            goal,
            active_state,
            retained_pinned_memories,
            retained_memories,
            checkpoint,
            runtime_authorization,
        )

        while retained_pinned_memories or retained_memories:
            protected = self.counter.count_request(
                [system_message, runtime_context],
                tools,
                self.serializer,
                profile,
                reserved_output_tokens=reserved_output_tokens,
            )
            if protected.total_with_reserve <= protected.context_window_tokens:
                break
            if retained_memories:
                retained_memories.pop()
            else:
                retained_pinned_memories.pop()
            system_message, runtime_context, category_text = self._system_message(
                system_rules,
                goal,
                active_state,
                retained_pinned_memories,
                retained_memories,
                checkpoint,
                runtime_authorization,
            )

        self.counter.assert_fits(
            [system_message, runtime_context],
            tools,
            self.serializer,
            profile,
            reserved_output_tokens=reserved_output_tokens,
        )

        full_messages = [system_message, *messages, runtime_context]
        full_breakdown = self.counter.count_request(
            full_messages,
            tools,
            self.serializer,
            profile,
            reserved_output_tokens=reserved_output_tokens,
        )
        trigger_tokens = int(
            profile.context_window_tokens
            * profile.compaction_trigger_ratio
        )
        requires_compaction = full_breakdown.total_with_reserve >= trigger_tokens
        selection_limit = profile.context_window_tokens
        if requires_compaction:
            selection_limit = int(
                profile.context_window_tokens
                * profile.compaction_target_ratio
            )

        groups = self._exchange_groups(messages)
        selected_groups: list[_ExchangeGroup] = []
        if full_breakdown.total_with_reserve <= selection_limit:
            selected_groups = groups
        else:
            for group in reversed(groups):
                candidate_groups = [group, *selected_groups]
                candidate_messages = [
                    message
                    for candidate_group in candidate_groups
                    for message in candidate_group.messages
                ]
                candidate_breakdown = self.counter.count_request(
                    [system_message, *candidate_messages, runtime_context],
                    tools,
                    self.serializer,
                    profile,
                    reserved_output_tokens=reserved_output_tokens,
                )
                if candidate_breakdown.total_with_reserve > selection_limit:
                    break
                selected_groups = candidate_groups

        open_groups = [group for group in groups if not group.closed]
        if open_groups:
            earliest_open = min(group.start for group in open_groups)
            selected_start = (
                selected_groups[0].start if selected_groups else len(messages)
            )
            if selected_start > earliest_open:
                selected_groups = [
                    group for group in groups if group.start >= earliest_open
                ]

        retained = [
            message for group in selected_groups for message in group.messages
        ]
        retained_start = (
            selected_groups[0].start if selected_groups else len(messages)
        )
        retained_indexes = list(range(retained_start, len(messages)))
        planned_messages = [system_message, *retained, runtime_context]
        breakdown = self.counter.assert_fits(
            planned_messages,
            tools,
            self.serializer,
            profile,
            reserved_output_tokens=reserved_output_tokens,
        )

        compactable_from: int | None = None
        compactable_to: int | None = None
        if retained_start > 0:
            omitted_groups = [group for group in groups if group.end < retained_start]
            if any(not group.closed for group in omitted_groups):
                raise ContextHardLimitExceeded(breakdown)
            compactable_from = 0
            compactable_to = retained_start - 1

        recent_history_text = json.dumps(
            retained,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        return ContextPlan(
            messages=planned_messages,
            tools=self.serializer.serialize_tools(tools),
            breakdown=breakdown,
            system_tokens=self.counter.count_text(category_text["system"]),
            working_state_tokens=self.counter.count_text(category_text["working_state"]),
            checkpoint_tokens=self.counter.count_text(category_text["checkpoint"]),
            recent_history_tokens=self.counter.count_text(recent_history_text),
            memory_tokens=self.counter.count_text(category_text["memories"]),
            pinned_memory_tokens=self.counter.count_text(
                category_text["pinned_memories"]
            ),
            retrieved_memory_tokens=self.counter.count_text(
                category_text["retrieved_memories"]
            ),
            tool_schema_tokens=breakdown.tool_schema_tokens,
            estimated_input_tokens=breakdown.input_tokens,
            reserved_output_tokens=breakdown.reserved_output_tokens,
            safety_margin_tokens=breakdown.safety_margin_tokens,
            context_window_tokens=breakdown.context_window_tokens,
            requires_compaction=requires_compaction,
            compactable_from=compactable_from,
            compactable_to=compactable_to,
            recent_tail_from=retained_start,
            retained_message_indexes=retained_indexes,
        )

    # [maint-note:794231b38ae6]
    # 维护导航：_system_message；下列为本函数源码中的接口与路径索引。
    # 输入 system_rules：str。
    # 输入 goal：str。
    # 输入 active_state：dict[str, Any]。
    # 输入 pinned_memories：list[dict[str, Any]]。
    # 输入 memories：list[dict[str, Any]]。
    # 输入 checkpoint：dict[str, Any] | None。
    # 输入 runtime_authorization：dict[str, Any]。
    # 返回契约：tuple[dict[str, Any], dict[str, Any], dict[str, str]]。
    # 分支条件：checkpoint is not None。
    # 分支条件：checkpoint_text。
    # 返回路径：({'role': 'system', 'content': '\n\n'.join(parts)}, {'role': 'user', 'content': f'[RUNTIME_CONTEXT]\n{retrieved_memory_block}\n\n{active_state_text}\n[/RUNTIME_CONTEXT]'}, {'system': f'{system_rules}\n\n{_RUNTIME_CONTEXT_GUIDANCE}', 'workin。
    # 直接调用：self._format_memories。
    # 直接调用：json.dumps。
    # 直接调用：_format_runtime_authorization。
    # 直接调用：parts.append。
    # 直接调用：parts.extend。
    # 直接调用：'\n\n'.join。
    # [/maint-note:794231b38ae6]
    def _system_message(
        self,
        system_rules: str,
        goal: str,
        active_state: dict[str, Any],
        pinned_memories: list[dict[str, Any]],
        memories: list[dict[str, Any]],
        checkpoint: dict[str, Any] | None,
        runtime_authorization: dict[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, str]]:
        pinned_memory_block = (
            "[PINNED_MEMORY_REFERENCES]\n"
            f"{self._format_memories(pinned_memories)}\n"
            "[/PINNED_MEMORY_REFERENCES]"
        )
        checkpoint_text = ""
        if checkpoint is not None:
            checkpoint_text = (
                "[CONTEXT_CHECKPOINT]\n"
                f"{json.dumps(checkpoint, ensure_ascii=False, sort_keys=True)}\n"
                "[/CONTEXT_CHECKPOINT]"
            )
        runtime_authorization_text = (
            "[RUNTIME_AUTHORIZATION]\n"
            f"{_format_runtime_authorization(runtime_authorization)}\n"
            "[/RUNTIME_AUTHORIZATION]"
        )
        goal_text = f"[USER_GOAL]\n{goal}\n[/USER_GOAL]"
        retrieved_memory_block = (
            "[RETRIEVED_MEMORY_REFERENCES]\n"
            f"{self._format_memories(memories)}\n"
            "[/RETRIEVED_MEMORY_REFERENCES]"
        )
        active_state_text = (
            "[ACTIVE_STATE]\n"
            f"{json.dumps(active_state, ensure_ascii=False, sort_keys=True)}\n"
            "[/ACTIVE_STATE]"
        )
        parts = [system_rules, pinned_memory_block]
        if checkpoint_text:
            parts.append(checkpoint_text)
        parts.extend(
            [
                runtime_authorization_text,
                goal_text,
                _RUNTIME_CONTEXT_GUIDANCE,
            ]
        )
        return (
            {"role": "system", "content": "\n\n".join(parts)},
            {
                "role": "user",
                "content": (
                    "[RUNTIME_CONTEXT]\n"
                    f"{retrieved_memory_block}\n\n{active_state_text}\n"
                    "[/RUNTIME_CONTEXT]"
                ),
            },
            {
                "system": f"{system_rules}\n\n{_RUNTIME_CONTEXT_GUIDANCE}",
                "working_state": active_state_text,
                "checkpoint": checkpoint_text,
                "pinned_memories": pinned_memory_block,
                "retrieved_memories": retrieved_memory_block,
                "memories": "\n\n".join(
                    [pinned_memory_block, retrieved_memory_block]
                ),
            },
        )

    # [maint-note:887061a13151]
    # 维护导航：_exchange_groups；下列为本函数源码中的接口与路径索引。
    # 输入 messages：list[dict[str, Any]]。
    # 返回契约：list[_ExchangeGroup]。
    # 分支条件：message.get('role') == 'assistant' and message.get('tool_calls')。
    # 分支条件：candidate.get('role') != 'tool' or tool_call_id not in call_ids。
    # 遍历边界：index < len(messages)。
    # 返回路径：groups。
    # 直接调用：len。
    # 直接调用：message.get。
    # 直接调用：str。
    # 直接调用：call.get。
    # 直接调用：set。
    # 直接调用：candidate.get。
    # 直接调用：group_messages.append。
    # 直接调用：seen_ids.add。
    # 直接调用：groups.append。
    # 直接调用：_ExchangeGroup。
    # 直接调用：bool。
    # 集合派生：call 来自 message.get('tool_calls', [])；过滤 call.get('id') is not None。
    # [/maint-note:887061a13151]
    def _exchange_groups(
        self, messages: list[dict[str, Any]]
    ) -> list[_ExchangeGroup]:
        groups: list[_ExchangeGroup] = []
        index = 0
        while index < len(messages):
            start = index
            message = messages[index]
            if message.get("role") == "assistant" and message.get("tool_calls"):
                call_ids = {
                    str(call.get("id"))
                    for call in message.get("tool_calls", [])
                    if call.get("id") is not None
                }
                seen_ids: set[str] = set()
                group_messages = [message]
                index += 1
                while index < len(messages):
                    candidate = messages[index]
                    tool_call_id = str(candidate.get("tool_call_id"))
                    if (
                        candidate.get("role") != "tool"
                        or tool_call_id not in call_ids
                    ):
                        break
                    group_messages.append(candidate)
                    seen_ids.add(tool_call_id)
                    index += 1
                groups.append(
                    _ExchangeGroup(
                        start=start,
                        end=index - 1,
                        messages=group_messages,
                        closed=bool(call_ids) and seen_ids == call_ids,
                    )
                )
            else:
                groups.append(
                    _ExchangeGroup(
                        start=start,
                        end=start,
                        messages=[message],
                    )
                )
                index += 1
        return groups

    # [maint-note:4f1f8e61b12f]
    # 维护导航：_format_memories；下列为本函数源码中的接口与路径索引。
    # 输入 memories：list[dict[str, Any]]。
    # 返回契约：str。
