class ContextBuilder:
    # [maint-note:20c801010cba]
    # 维护导航：__init__；下列为本函数源码中的接口与路径索引。
    # 输入 max_chars：int；缺省表达式 40000。
    # 返回契约：None。
    # 分支条件：max_chars < 200。
    # 显式抛出：ValueError('max_chars must be at least 200')。
    # 写入目标：self.max_chars。
    # 直接调用：ValueError。
    # [/maint-note:20c801010cba]
    def __init__(self, max_chars: int = 40_000) -> None:
        if max_chars < 200:
            raise ValueError("max_chars must be at least 200")
        self.max_chars = max_chars

    # [maint-note:ba49235f8b88]
    # 维护导航：build；下列为本函数源码中的接口与路径索引。
    # 输入 system_rules：str。
    # 输入 goal：str。
    # 输入 messages：list[dict[str, Any]]。
    # 输入 active_state：dict[str, Any]。
    # 输入 memories：list[dict[str, Any]]。
    # 输入 pinned_memories：list[dict[str, Any]] | None；缺省表达式 None。
    # 输入 runtime_authorization：dict[str, Any] | None；缺省表达式 None。
    # 返回契约：list[dict[str, Any]]。
    # 分支条件：selected and used + size > budget。
    # 分支条件：used >= budget。
    # 分支条件：omitted_messages。
    # 遍历边界：group ← reversed(groups)。
    # 返回路径：[system, *flattened, runtime_context]。
    # 直接调用：self._format_memories。
    # 直接调用：list。
    # 直接调用：_format_runtime_authorization。
    # 直接调用：json.dumps。
    # 直接调用：max。
    # 直接调用：len。
    # 直接调用：self._exchange_groups。
    # 直接调用：reversed。
    # 直接调用：selected.append。
    # 直接调用：selected.reverse。
    # 直接调用：id。
    # 直接调用：flattened.insert。
    # 直接调用：self._summarize_messages。
    # 集合派生：group 来自 selected。
    # 集合派生：message 来自 group。
    # 集合派生：message 来自 flattened。
    # 集合派生：message 来自 messages；过滤 id(message) not in selected_message_ids。
    # [/maint-note:ba49235f8b88]
    def build(
        self,
        *,
        system_rules: str,
        goal: str,
        messages: list[dict[str, Any]],
        active_state: dict[str, Any],
        memories: list[dict[str, Any]],
        pinned_memories: list[dict[str, Any]] | None = None,
        runtime_authorization: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        pinned_memory_block = (
            "[PINNED_MEMORY_REFERENCES]\n"
            f"{self._format_memories(list(pinned_memories or []))}\n"
            "[/PINNED_MEMORY_REFERENCES]"
        )
        retrieved_memory_block = (
            "[RETRIEVED_MEMORY_REFERENCES]\n"
            f"{self._format_memories(memories)}\n"
            "[/RETRIEVED_MEMORY_REFERENCES]"
        )
        system = {
            "role": "system",
            "content": (
                f"{system_rules}\n\n"
                f"{pinned_memory_block}\n\n"
                "[RUNTIME_AUTHORIZATION]\n"
                f"{_format_runtime_authorization(runtime_authorization or {})}\n"
                "[/RUNTIME_AUTHORIZATION]\n\n"
                f"[USER_GOAL]\n{goal}\n[/USER_GOAL]\n\n"
                f"{_RUNTIME_CONTEXT_GUIDANCE}"
            ),
        }
        runtime_context = {
            "role": "user",
            "content": (
                "[RUNTIME_CONTEXT]\n"
                f"{retrieved_memory_block}\n\n"
                f"[ACTIVE_STATE]\n{json.dumps(active_state, ensure_ascii=False, sort_keys=True)}\n[/ACTIVE_STATE]\n"
                "[/RUNTIME_CONTEXT]"
            ),
        }
        budget = max(0, self.max_chars - len(system["content"]) - len(runtime_context["content"]))
        groups = self._exchange_groups(messages)
        selected: list[list[dict[str, Any]]] = []
        used = 0
        for group in reversed(groups):
            size = len(json.dumps(group, ensure_ascii=False))
            if selected and used + size > budget:
                continue
            selected.append(group)
            used += size
            if used >= budget:
                break
        selected.reverse()
        flattened = [message for group in selected for message in group]
        selected_message_ids = {id(message) for message in flattened}
        omitted_messages = [message for message in messages if id(message) not in selected_message_ids]
        if omitted_messages:
            flattened.insert(
                0,
                {
                    "role": "system",
                    "content": (
                        "[HISTORY_SUMMARY]\n"
                        f"{self._summarize_messages(omitted_messages)}\n"
                        "[/HISTORY_SUMMARY]\n"
                        "This is a derived summary; authoritative events remain persisted."
                    ),
                },
            )
        return [system, *flattened, runtime_context]

    # [maint-note:24a8c7682ac7]
    # 维护导航：_exchange_groups；下列为本函数源码中的接口与路径索引。
    # 输入 messages：list[dict[str, Any]]。
    # 返回契约：list[list[dict[str, Any]]]。
    # 分支条件：message.get('role') == 'assistant' and message.get('tool_calls')。
    # 分支条件：candidate.get('role') != 'tool' or candidate.get('tool_call_id') not in call_ids。
    # 分支条件：len(group) == 1。
    # 遍历边界：index < len(messages)。
    # 返回路径：groups。
    # 直接调用：len。
    # 直接调用：message.get。
    # 直接调用：call.get。
    # 直接调用：candidate.get。
    # 直接调用：group.append。
    # 直接调用：groups.append。
    # 集合派生：call 来自 message.get('tool_calls', [])。
    # [/maint-note:24a8c7682ac7]
    def _exchange_groups(self, messages: list[dict[str, Any]]) -> list[list[dict[str, Any]]]:
        groups: list[list[dict[str, Any]]] = []
        index = 0
        while index < len(messages):
            message = messages[index]
            if message.get("role") == "assistant" and message.get("tool_calls"):
                call_ids = {call.get("id") for call in message.get("tool_calls", [])}
                group = [message]
                index += 1
                while index < len(messages):
                    candidate = messages[index]
                    if candidate.get("role") != "tool" or candidate.get("tool_call_id") not in call_ids:
                        break
                    group.append(candidate)
                    index += 1
                if len(group) == 1:
                    continue
                groups.append(group)
            else:
                groups.append([message])
                index += 1
        return groups

    # [maint-note:13237d07ba12]
    # 维护导航：_format_memories；下列为本函数源码中的接口与路径索引。
    # 输入 memories：list[dict[str, Any]]。
    # 返回契约：str。
    # 返回路径：_format_memory_items(memories)。
    # 直接调用：_format_memory_items。
    # [/maint-note:13237d07ba12]
    def _format_memories(self, memories: list[dict[str, Any]]) -> str:
        return _format_memory_items(memories)

    # [maint-note:49fa8883c080]
    # 维护导航：_summarize_messages；下列为本函数源码中的接口与路径索引。
    # 输入 messages：list[dict[str, Any]]。
    # 输入 max_chars：int；缺省表达式 1200。
    # 返回契约：str。
    # 分支条件：role == 'assistant' and message.get('tool_calls')。
    # 分支条件：role == 'tool'。
    # 分支条件：sum((len(item) + 1 for item in lines)) + len(line) > max_chars。
    # 遍历边界：message ← messages。
    # 返回路径：'\n'.join(lines) or '- no textual history'。
    # 直接调用：str。
    # 直接调用：message.get。
    # 直接调用：' '.join。
    # 直接调用：str(message.get('content', '')).split。
    # 直接调用：', '.join。
    # 直接调用：call.get。
    # 直接调用：sum。
    # 直接调用：len。
    # 直接调用：lines.append。
    # 直接调用：'\n'.join。
    # 集合派生：call 来自 message.get('tool_calls', [])。
    # 集合派生：item 来自 lines。
    # [/maint-note:49fa8883c080]
    def _summarize_messages(self, messages: list[dict[str, Any]], max_chars: int = 1_200) -> str:
        lines: list[str] = []
        for message in messages:
            role = str(message.get("role", "unknown"))
            content = " ".join(str(message.get("content", "")).split())
            if role == "assistant" and message.get("tool_calls"):
                names = ", ".join(
                    str(call.get("name", "unknown")) for call in message.get("tool_calls", [])
                )
                line = f"- assistant requested tools: {names}"
            elif role == "tool":
                name = str(message.get("name", "unknown"))
                line = f"- tool {name}: {content[:160]}"
            else:
                line = f"- {role}: {content[:320]}"
            if sum(len(item) + 1 for item in lines) + len(line) > max_chars:
                lines.append("- additional history omitted")
                break
            lines.append(line)
        return "\n".join(lines) or "- no textual history"
